export type ModuleCategory = 'Cannon' | 'Armor' | 'Generator' | 'Core'
export type ModuleRarityLabel = string

export interface ModuleRarityBonus {
  rarity: ModuleRarityLabel
  value: number
}

export interface ModuleTemplate {
  id: string
  name: string
  initials: string
  type: ModuleCategory
  unique: boolean
  minRarity: ModuleRarityLabel
  maxRarity: ModuleRarityLabel
  description: (value?: number) => string
  baseEffect?: string
  rarityBonuses?: ModuleRarityBonus[]
}

