export const UNIQUE_MODULE_TEMPLATES = uniqueModules
export const RARE_MODULE_TEMPLATES = rareModules
export const COMMON_MODULE_TEMPLATES = commonModules

export const MODULE_TEMPLATES: ModuleTemplate[] = [
  ...uniqueModules,
  ...rareModules,
  ...commonModules,
]

export const MODULE_TEMPLATE_MAP: Record<string, ModuleTemplate> = MODULE_TEMPLATES.reduce((map, module) => {
  map[module.id] = module
  return map
}, {} as Record<string, ModuleTemplate>)

export function getModuleTemplate(id: string): ModuleTemplate | undefined {
  // Module ids come from saves, so own keys only — `getModuleTemplate('constructor')`
  // otherwise returns a function rather than a template or `undefined`.
  if (!Object.prototype.hasOwnProperty.call(MODULE_TEMPLATE_MAP, id)) return undefined
  return MODULE_TEMPLATE_MAP[id]
}

export function getModulesByType(type: ModuleCategory): ModuleTemplate[] {
  return MODULE_TEMPLATES.filter(module => module.type === type)
}
